{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2188-11-08 15:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be taking care of you during your stay. Can you tell me what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2188-11-08 15:16:30",
      "speaker": "Patient",
      "text": "Yeah, I’ve had this sharp pain in my lower left side for about three weeks. It got a lot worse the last couple days."
    },
    {
      "turn_number": 3,
      "time": "2188-11-08 15:17:15",
      "speaker": "Doctor",
      "text": "Any other symptoms? Fever, nausea, vomiting?"
    },
    {
      "turn_number": 4,
      "time": "2188-11-08 15:18:00",
      "speaker": "Patient",
      "text": "I threw up once yesterday, not bloody. No fever. But my urine looked thick and cloudy."
    },
    {
      "turn_number": 5,
      "time": "2188-11-08 15:19:00",
      "speaker": "Doctor",
      "text": "Okay. Given your history with the Foley catheter and past infections, we’re concerned this could be a kidney infection."
    },
    {
      "turn_number": 6,
      "time": "2188-11-08 15:20:15",
      "speaker": "Patient",
      "text": "Like pyelonephritis again? I’ve had that before."
    },
    {
      "turn_number": 7,
      "time": "2188-11-08 15:21:00",
      "speaker": "Doctor",
      "text": "Exactly. We’ve started you on IV antibiotics—levofloxacin—for now. We also did a CT scan to check for kidney stones."
    },
    {
      "turn_number": 8,
      "time": "2188-11-08 15:22:00",
      "speaker": "Patient",
      "text": "Did it show any stones?"
    },
    {
      "turn_number": 9,
      "time": "2188-11-08 15:23:00",
      "speaker": "Doctor",
      "text": "No stones, no blockage. That’s good. Your kidneys look clear. But the pain in your lower left side and the pus in your urine point to infection."
    },
    {
      "turn_number": 10,
      "time": "2188-11-08 15:24:15",
      "speaker": "Patient",
      "text": "So it’s not my bowels? I’ve been backed up."
    },
    {
      "turn_number": 11,
      "time": "2188-11-08 15:25:00",
      "speaker": "Doctor",
      "text": "We did manually disimpact you in the ER. That’s done now. Your belly sounds normal, so we don’t think constipation is the main issue."
    },
    {
      "turn_number": 12,
      "time": "2188-11-08 15:26:00",
      "speaker": "Patient",
      "text": "Okay, thanks. I was really uncomfortable."
    },
    {
      "turn_number": 13,
      "time": "2188-11-08 15:27:00",
      "speaker": "Doctor",
      "text": "We also placed a femoral line because your veins are hard to access. It’ll help with fluids and meds."
    },
    {
      "turn_number": 14,
      "time": "2188-11-08 15:28:00",
      "speaker": "Patient",
      "text": "Yeah, I know it’s tough to get an IV. Thanks for getting it done."
    },
    {
      "turn_number": 15,
      "time": "2188-11-08 18:00:00",
      "speaker": "Doctor",
      "text": "Your urine culture came back. It’s E. coli, which is common. It’s sensitive to the antibiotics we’re using."
    },
    {
      "turn_number": 16,
      "time": "2188-11-08 18:01:30",
      "speaker": "Patient",
      "text": "So I’ll keep getting the IV meds?"
    },
    {
      "turn_number": 17,
      "time": "2188-11-08 18:02:30",
      "speaker": "Doctor",
      "text": "For now, yes. We’ll switch you to oral antibiotics once you’re stable. We’re using ceftriaxone IV until then."
    },
    {
      "turn_number": 18,
      "time": "2188-11-08 18:03:30",
      "speaker": "Patient",
      "text": "Okay. I’m glad it’s not resistant or anything."
    },
    {
      "turn_number": 19,
      "time": "2188-11-09 09:15:00",
      "speaker": "Doctor",
      "text": "Good morning. How’s the pain today?"
    },
    {
      "turn_number": 20,
      "time": "2188-11-09 09:16:30",
      "speaker": "Patient",
      "text": "Still there, but not as bad. I haven’t thrown up, and I’m hungry."
    },
    {
      "turn_number": 21,
      "time": "2188-11-09 09:17:30",
      "speaker": "Doctor",
      "text": "That’s a good sign. We’re going to try you on solid food. Your white blood cell count went up yesterday but is stabilizing."
    },
    {
      "turn_number": 22,
      "time": "2188-11-09 09:18:30",
      "speaker": "Patient",
      "text": "Is that bad?"
    },
    {
      "turn_number": 23,
      "time": "2188-11-09 09:19:30",
      "speaker": "Doctor",
      "text": "It’s expected with infection. It’s coming down now, so you’re responding to treatment."
    },
    {
      "turn_number": 24,
      "time": "2188-11-09 09:20:30",
      "speaker": "Patient",
      "text": "Good. I just want to feel normal again."
    },
    {
      "turn_number": 25,
      "time": "2188-11-09 14:00:00",
      "speaker": "Doctor",
      "text": "We checked your HbA1c. It’s 6.5%, which means you’re in the prediabetes range."
    },
    {
      "turn_number": 26,
      "time": "2188-11-09 14:01:30",
      "speaker": "Patient",
      "text": "I was on insulin before, but I stopped. I didn’t have access."
    },
    {
      "turn_number": 27,
      "time": "2188-11-09 14:02:30",
      "speaker": "Doctor",
      "text": "We’re not starting meds now, but we’ve scheduled an appointment with your PCP within the week. You should follow a diabetic diet—less sugar, more veggies."
    },
    {
      "turn_number": 28,
      "time": "2188-11-09 14:03:30",
      "speaker": "Patient",
      "text": "I can try. It’s hard when I don’t have a kitchen."
    },
    {
      "turn_number": 29,
      "time": "2188-11-09 14:04:30",
      "speaker": "Doctor",
      "text": "We’ll talk to social work. They might help with resources."
    },
    {
      "turn_number": 30,
      "time": "2188-11-10 10:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Pain is better, no fever, eating normally. We’re switching you to oral antibiotics today."
    },
    {
      "turn_number": 31,
      "time": "2188-11-10 10:01:30",
      "speaker": "Patient",
      "text": "What kind?"
    },
    {
      "turn_number": 32,
      "time": "2188-11-10 10:02:30",
      "speaker": "Doctor",
      "text": "Cefpodoxime—two pills twice a day for 11 more days. It covers the same bacteria as the IV meds."
    },
    {
      "turn_number": 33,
      "time": "2188-11-10 10:03:30",
      "speaker": "Patient",
      "text": "I can take that at home?"
    },
    {
      "turn_number": 34,
      "time": "2188-11-10 10:04:30",
      "speaker": "Doctor",
      "text": "Yes. As long as you finish the whole course, even if you feel better."
    },
    {
      "turn_number": 35,
      "time": "2188-11-10 10:05:30",
      "speaker": "Patient",
      "text": "I’ll do that. I don’t want this coming back."
    },
    {
      "turn_number": 36,
      "time": "2188-11-10 14:30:00",
      "speaker": "Doctor",
      "text": "We also reviewed your meds. We’re cutting your amitriptyline in half and reducing fluoxetine."
    },
    {
      "turn_number": 37,
      "time": "2188-11-10 14:31:30",
      "speaker": "Patient",
      "text": "Why? I’ve been on those for years."
    },
    {
      "turn_number": 38,
      "time": "2188-11-10 14:32:30",
      "speaker": "Doctor",
      "text": "Amitriptyline at 100 mg can cause side effects, especially with your other meds. Fluoxetine dose was high—we’re adjusting for safety."
    },
    {
      "turn_number": 39,
      "time": "2188-11-10 14:33:30",
      "speaker": "Patient",
      "text": "Okay, I trust you. But I don’t want my mood to drop."
    },
    {
      "turn_number": 40,
      "time": "2188-11-10 14:34:30",
      "speaker": "Doctor",
      "text": "We’re monitoring that. You’ve denied suicidal thoughts, which is good. Keep taking it as prescribed and follow up with your psychiatrist."
    },
    {
      "turn_number": 41,
      "time": "2188-11-11 08:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home today. You’re afebrile, pain is much better, and labs are improving."
    },
    {
      "turn_number": 42,
      "time": "2188-11-11 08:01:30",
      "speaker": "Patient",
      "text": "That’s great. But it’s drizzling outside, and my aunt’s not home yet."
    },
    {
      "turn_number": 43,
      "time": "2188-11-11 08:02:30",
      "speaker": "Doctor",
      "text": "Social work reached another aunt. She’s willing to take you in tonight until your regular aunt is back."
    },
    {
      "turn_number": 44,
      "time": "2188-11-11 08:03:30",
      "speaker": "Patient",
      "text": "Oh. I didn’t give her name, but okay. I guess that’s fine."
    },
    {
      "turn_number": 45,
      "time": "2188-11-11 08:04:30",
      "speaker": "Doctor",
      "text": "We want to make sure you’re safe. You’ll need to rest and take your antibiotics."
    },
    {
      "turn_number": 46,
      "time": "2188-11-11 08:05:30",
      "speaker": "Patient",
      "text": "And follow up for the diabetes?"
    },
    {
      "turn_number": 47,
      "time": "2188-11-11 08:06:30",
      "speaker": "Doctor",
      "text": "Yes, your PCP appointment is set. Call if you develop fever, pain, or can’t keep the meds down."
    },
    {
      "turn_number": 48,
      "time": "2188-11-11 08:07:30",
      "speaker": "Patient",
      "text": "I will. Thank you for everything."
    },
    {
      "turn_number": 49,
      "time": "2188-11-11 08:08:30",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care of yourself. We’re discharging you on cefpodoxime, and your other meds are adjusted as discussed."
    },
    {
      "turn_number": 50,
      "time": "2188-11-11 08:09:30",
      "speaker": "Patient",
      "text": "Got it. I’ll finish the antibiotics and eat better."
    },
    {
      "turn_number": 51,
      "time": "2188-11-11 10:30:00",
      "speaker": "Doctor",
      "text": "Just a quick check before you leave. Any new symptoms?"
    },
    {
      "turn_number": 52,
      "time": "2188-11-11 10:31:00",
      "speaker": "Patient",
      "text": "No, still feeling better. Ready to go."
    },
    {
      "turn_number": 53,
      "time": "2188-11-11 10:32:00",
      "speaker": "Doctor",
      "text": "Good. Remember—diabetes follow-up, finish antibiotics, and call if anything changes."
    },
    {
      "turn_number": 54,
      "time": "2188-11-11 10:33:00",
      "speaker": "Patient",
      "text": "I’ll do that. Thanks again."
    },
    {
      "turn_number": 55,
      "time": "2188-11-11 12:00:00",
      "speaker": "Doctor",
      "text": "Your discharge instructions are printed. The pharmacy has your prescription ready."
    },
    {
      "turn_number": 56,
      "time": "2188-11-11 12:01:00",
      "speaker": "Patient",
      "text": "Okay, I’ll pick it up before I leave."
    },
    {
      "turn_number": 57,
      "time": "2188-11-11 12:02:00",
      "speaker": "Doctor",
      "text": "And we’ve given you a copy of your diabetic diet tips. Try to stick to it."
    },
    {
      "turn_number": 58,
      "time": "2188-11-11 12:03:00",
      "speaker": "Patient",
      "text": "I’ll do my best. Appreciate the help."
    },
    {
      "turn_number": 59,
      "time": "2188-11-11 12:04:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Stay in touch with your doctors."
    },
    {
      "turn_number": 60,
      "time": "2188-11-11 12:05:00",
      "speaker": "Patient",
      "text": "I will. Take care."
    }
  ],
  "summary": {
    "admission_start": "2188-11-08 15:08:00",
    "admission_end": "2188-11-11 19:20:00",
    "summary_paragraph": "A woman with a history of paraplegia, neurogenic bladder, and chronic indwelling Foley catheter presented with worsening left lower quadrant abdominal pain, nausea, and purulent urine. She was diagnosed with acute pyelonephritis caused by E. coli, treated initially with IV ceftriaxone, and transitioned to oral cefpodoxime for completion of a two-week course. During admission, she was found to have a borderline diabetic HbA1c of 6.5%, prompting a scheduled follow-up with her primary care provider and dietary counseling. Her pain improved, she remained afebrile, and she was discharged home with medication adjustments, including reduced doses of amitriptyline and fluoxetine. Social work facilitated temporary housing through a family member due to her homelessness.",
    "problems": [
      "Acute pyelonephritis without lesion of renal medullary necrosis",
      "Paraplegia",
      "Other impaction of intestine",
      "Diabetes mellitus without mention of complication, type II or unspecified type, uncontrolled",
      "Neurogenic bladder NOS",
      "Escherichia coli [E. coli] infection in conditions classified elsewhere and of unspecified site",
      "Other and unspecified alcohol dependence, continuous",
      "Cocaine abuse, unspecified",
      "Incontinence of feces",
      "Late effects of injuries due to legal intervention",
      "Below knee amputation status",
      "Lack of housing"
    ]
  }
}
